// Both triggers end here with the same shape: json.job_text + binary.cv (the CV file).
const it = $input.first();
const jobText = it.json.job_text ?? (it.json.body ?? {}).job_text;
if (!jobText) throw new Error('job_text is missing (multipart field "job_text")');
if (!it.binary || !it.binary.cv) throw new Error('CV file is missing (multipart field "cv")');
const reqs = it.json.requirements ?? (it.json.body ?? {}).requirements ?? '';
return [{ json: { job_text: String(jobText), requirements_json: String(reqs || '') }, binary: { cv: it.binary.cv } }];

// The recruiter confirmed the requirement list (T08b, human-in-the-loop at job level): /job is skipped.
const card = JSON.parse($('Normalize input').first().json.requirements_json);
const reqs = card.requirements || [];
if (!reqs.length) throw new Error('confirmed requirements: empty list');
for (const r of reqs) {
  if (!r.req_id || !r.text || !['must', 'nice'].includes(r.kind)) throw new Error('confirmed requirement needs req_id, text, kind must|nice');
}
return [{ json: {
  card: { job_id: card.job_id || 'job-confirmed', title: card.title || '', language: 'en',
          requirements: reqs.map(r => ({ req_id: r.req_id, text: r.text, kind: r.kind, category: r.category || 'skill',
                                         min_years: r.min_years ?? null, skill_terms: r.skill_terms || [],
                                         evidence: r.evidence || r.text, chunk_ids: [] })),
          uncertain: [], needs_human_review: false, warnings: [] },
  injection: { injected_sentences: [], dropped_req_ids: [] }, review_reasons: [],
  info_flags: ['job:requirements confirmed by recruiter'], elapsed_s: 0 } }];

// One item per requirement: the anonymised CV text (never the raw text) + the requirement card.
const p = $('HTTP /profile').first().json;
const job = $('Job card').first().json;
return job.card.requirements.map(r => ({ json: {
  cv_id: p.cv_id, cv_text: p.anonymised_text,
  requirement: { req_id: r.req_id, text: r.text, kind: r.kind, category: r.category,
                 skill_terms: r.skill_terms, min_years: r.min_years },
} }));

// Station 8 input: every requirement result of the pair + the pair-level flags (reader / profile / job).
const reader = $('HTTP /reader').first().json, profile = $('HTTP /profile').first().json, job = $('Job card').first().json;
const bias = $('Bias Auditor').first().json;  // station 5 (T11)
const card = Object.fromEntries(job.card.requirements.map(r => [r.req_id, r]));
return [{ json: {
  cv_id: profile.cv_id, job_id: job.card.job_id,
  requirements: $('Aggregate').first().json.matches.map(m => ({ req_id: m.req_id, kind: card[m.req_id].kind, decision: m.decision,
                                          review_reasons: m.review_reasons, info_flags: m.info_flags,
                                          category: card[m.req_id].category, min_years: card[m.req_id].min_years,
                                          evidence_years: m.evidence_years,
                                          confidence: m.confidence ? m.confidence.normalized : null,
                                          judge: m.judge ? { verdict: m.judge.verdict, nli_probs: m.judge.nli_probs } : null })),
  pair_review_reasons: [...reader.review_reasons, ...profile.review_reasons, ...job.review_reasons, ...bias.review_reasons],
  pair_info_flags: [...reader.info_flags, ...profile.info_flags, ...job.info_flags, ...bias.info_flags],
} }];

// The pair result: the gate's outcome (HTTP /outcome) + per-requirement details and timings (code only, no model).
const gate = $('HTTP /outcome').first().json, rep = $json, job = $('Job card').first().json, profile = $('HTTP /profile').first().json;
const reader = $('HTTP /reader').first().json, matches = $('Aggregate').first().json.matches;
const card = Object.fromEntries(job.card.requirements.map(r => [r.req_id, r]));
return [{ json: {
  workflow: 'HireSignal v1', execution_id: $execution.id, cv_id: profile.cv_id, job_id: job.card.job_id,
  job_title: job.card.title, outcome: gate.outcome, rule: gate.rule, score: gate.score, reasons: gate.reasons,
  listed_flags: gate.listed_flags, message: gate.message, gate_settings: gate.settings, decided_by: 'gate',
  review_form_url: gate.outcome === 'review' ? $execution.resumeFormUrl : null,
  requirements: matches.map(m => ({ req_id: m.req_id, text: card[m.req_id].text, kind: card[m.req_id].kind,
    decision: m.decision, model_decision: m.model_decision, basis: m.basis, quotes: m.evidence,
    explanation: m.explanation, review_reasons: m.review_reasons, info_flags: m.info_flags,
    confidence: m.confidence ? m.confidence.normalized : null,
    judge: m.judge ? { verdict: m.judge.verdict, score: m.judge.score } : null, lora_scale: m.model.lora_scale })),
  report: { recruiter_summary: rep.report.recruiter_summary, requirements: rep.report.requirements, candidate_letter: rep.report.candidate_letter, flags_for_recruiter: rep.report.flags_for_recruiter, source: rep.source, info_flags: rep.info_flags, model: rep.model },
  bias: (b => ({ bias_flags: b.bias_flags, would_be_outcome: b.would_be_outcome, swap: b.swap, review_reasons: b.review_reasons }))($('Bias Auditor').first().json),
  reader: { file_type: reader.file_type, mode: reader.mode, read_path: reader.read_path, pages: reader.pages,
            ocr_confidence: reader.ocr_confidence, review_reasons: reader.review_reasons },
  timings_s: { reader: reader.elapsed_s, profile: profile.elapsed_s, job: job.elapsed_s,
               match_and_judge: Math.round(1000 * matches.reduce((a, m) => a + m.elapsed_s, 0)) / 1000 },
} }];

// Decided by the gate (invite or reject): keep the gate's result; rejects carry the reasons + the review sentence.
const r = { ...$json, final_decision: $json.outcome, decided_at: new Date().toISOString() };
if (r.outcome === 'reject') r.message = 'You can request a human review of this decision.';
return [{ json: r }];

// The recruiter answered the review form: final decision by a human (decided_by: human).
const form = $json, gate = $('Result').first().json;
const answer = form['Decision'] || form['decision'];
const final = answer === 'approve-invite' ? 'invite' : 'reject';
return [{ json: { ...gate, final_decision: final, decided_by: 'human', human_note: form['Note'] || form['note'] || '',
                  decided_at: new Date().toISOString(),
                  message: final === 'reject' ? 'You can request a human review of this decision.' : null } }];

// Outbox file (stands in for the e-mail): eval/outbox/<decision>/<execution>_<cv_id>.json
const r = $json, d = r.final_decision;
// T12/T13: gate decisions use the Report Writer's checked letter; a human decision after review uses the
// Report Writer (human decision) letter; the fixed letter is only the last resort.
const fixed = { invite: 'Dear candidate,\n\nThank you for your application. We would like to invite you to the next step of the process.\n\nKind regards',
                reject: 'Dear candidate,\n\nThank you for your application. After a review by our team, we will not move forward with it.\n\nKind regards' };
const letter = (r.decided_by === 'gate' && r.report && r.report.candidate_letter) ? r.report.candidate_letter
  : (r.human_report && r.human_report.candidate_letter) ? r.human_report.candidate_letter : fixed[d];
return [{ json: { ...r, letter, path: 'eval/outbox/' + d + '/' + r.execution_id + '_' + r.cv_id + '.json',
                  file_text: JSON.stringify({ ...r, letter }, null, 1) } }];

// T13: the human decision + its checked letter (Report Writer, decided_by: human)
const r = $('Decided by human').first().json;
return [{ json: { ...r, human_report: { candidate_letter: $json.report.candidate_letter, source: $json.source, info_flags: $json.info_flags } } }];
